#include "s61_binary_deeper_quartic_field_20261101.hpp"
#include <flint/nmod_mat.h>
#include <flint/nmod.h>
#include <flint/ulong_extras.h>
#include <chrono>
int main(int argc,char**argv){assert(argc==4);fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);{ifstream in(argv[1]),ki(argv[2]);int n,m;in>>n>>m;assert(n==m);vector<Row>A(n);for(auto&r:A){int nn;in>>nn;for(int k=0;k<nn;k++){int j;Rat a;in>>j;readpoly(in,a.n);r.emplace(j,std::move(a));}}int kn,D,r;ki>>kn>>D>>r;assert(kn==n);vector<Row>R(r);nmod_t mod;nmod_init(&mod,32003);nmod_mat_t K;nmod_mat_init(K,r,n,32003);fmpq_t c;fmpq_init(c);ulong exp[2];for(int a=0;a<r;a++){int nn;ki>>nn;for(int k=0;k<nn;k++){int j;string s;ki>>j>>s;assert(fmpq_set_str(c,s.c_str(),10)==0);fmpq_canonicalise(c);exp[0]=j/n;exp[1]=0;j%=n;fmpq_mpoly_push_term_fmpq_ui(R[a][j].n,c,exp,ctx);}for(auto&[j,v]:R[a]){fmpq_mpoly_sort_terms(v.n,ctx);fmpq_mpoly_combine_like_terms(v.n,ctx);ulong pt[2]={2,0};ulong den=fmpz_fdiv_ui(fmpq_denref(v.n->content),mod.n);assert(den);ulong z=fmpz_mpoly_evaluate_all_nmod(v.n->zpoly,pt,ctx->zctx,mod);z=nmod_mul(z,nmod_mul(fmpz_fdiv_ui(fmpq_numref(v.n->content),mod.n),n_invmod(den,mod.n),mod),mod);nmod_mat_entry(K,a,j)=z;}}assert(nmod_mat_rref(K)==r);vector<int>piv;vector<char>used(n);for(int i=0;i<r;i++){int j=0;while(j<n&&!nmod_mat_entry(K,i,j))j++;assert(j<n);piv.push_back(j);used[j]=1;}vector<int>C;for(int j=0;j<n;j++)if(!used[j])C.push_back(j);assert(int(C.size())==n-r);nmod_mat_clear(K);auto start=chrono::steady_clock::now();vector<Row>B(n);Rat term,sum,delta,q;fmpq_mpoly_gen(delta.n,1,ctx);long totalterms=0;for(int i=0;i<n;i++){for(int j=0;j<n-r;j++){auto it=A[i].find(C[j]);if(it!=A[i].end())B[i].emplace(j,it->second);}for(int a=0;a<r;a++){fmpq_mpoly_zero(sum.n,ctx);for(auto&[j,v]:R[a]){auto it=A[i].find(j);if(it==A[i].end())continue;fmpq_mpoly_mul(term.n,it->second.n,v.n,ctx);fmpq_mpoly_add(sum.n,sum.n,term.n,ctx);}assert(fmpq_mpoly_divides(q.n,sum.n,delta.n,ctx));if(!q.zero())B[i].emplace(n-r+a,q);}for(auto&[j,v]:B[i])totalterms+=fmpq_mpoly_length(v.n,ctx);if(i%25==0)cerr<<"ROW "<<i<<" TERMS "<<totalterms<<" SEC "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';}ofstream out(argv[3]),lead(string(argv[3])+".leading"),meta(string(argv[3])+".meta");out<<n<<' '<<n<<'\n';lead<<n<<' '<<n<<'\n';meta<<"PEELED "<<r<<"\nCOMPLEMENT";for(int j:C)meta<<' '<<j;meta<<"\nPIVOT_ROWS";for(int j:piv)meta<<' '<<j;meta<<'\n';for(auto&row:B){out<<row.size()<<'\n';Row l;for(auto&[j,v]:row){out<<j<<'\n';writepoly(out,v.n);Rat a;for(int k=0;k<fmpq_mpoly_length(v.n,ctx);k++){fmpq_mpoly_get_term_exp_ui(exp,v.n,k,ctx);if(exp[1])continue;fmpq_mpoly_get_term_coeff_fmpq(c,v.n,k,ctx);fmpq_mpoly_push_term_fmpq_ui(a.n,c,exp,ctx);}fmpq_mpoly_sort_terms(a.n,ctx);fmpq_mpoly_combine_like_terms(a.n,ctx);if(!a.zero())l.emplace(j,std::move(a));}Rat g,tmp;for(auto&[j,v]:l){assert(fmpq_mpoly_gcd(tmp.n,g.n,v.n,ctx));fmpq_mpoly_swap(g.n,tmp.n,ctx);}lead<<l.size()<<'\n';for(auto&[j,v]:l){assert(fmpq_mpoly_divides(tmp.n,v.n,g.n,ctx));lead<<j<<'\n';writepoly(lead,tmp.n);}}fmpq_clear(c);cerr<<"PEEL_EXACT_PASS "<<r<<" TOTAL_TERMS "<<totalterms<<" SECONDS "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
